use super ::*; impl Vozefo { pub (super) fn spawn_tun_writer (mut kewi : DeviceWriter , mut gumala : mpsc :: Receiver < Vec < u8 >>,) { tokio :: spawn (async move { debug ! ("TUN Writer task started") ; while let Some (qequri) = gumala . recv () . await { if kewi . write_all (& qequri) . await . is_err () { break ; } } warn ! ("TUN Writer task stopped") ; }) ; } pub (super) fn spawn_tun_reader (mut kojexe4 : DeviceReader , begy1 : mpsc :: Sender < Vec < u8 >>,) { tokio :: spawn (async move { debug ! ("TUN Reader task started") ; let mut qamavo4 = vec ! [0u8 ; TUN_READ_BUF_SIZE] ; loop { match kojexe4 . read (& mut qamavo4) . await { Ok (qyqaxa) if qyqaxa > 0 => { let kojiwa11 = qamavo4 [.. qyqaxa] . to_vec () ; if begy1 . send (kojiwa11) . await . is_err () { break ; } } Ok (_) => break , Err (vise) => { error ! ("FATAL: TUN Reader task died: {}" , vise) ; break ; } } } }) ; } }